    ("gov_m2_29", "Pre-Colonial Systems: King Jaja of Opobo", "2013", "The prominent Niger Delta merchant king deported by the British in 1887 for resisting colonial trade monopoly was:", ["King Jaja of Opobo", "Oba Ovonramwen of Benin", "Nana Olomu of Itsekiri", "King Kosoko of Lagos"], 0, "King Jaja of Opobo vehemently defended his sovereign monopoly of palm oil trade in the Oil Rivers and was exiled to the West Indies.", "Easy"),
    ("gov_m2_30", "Pre-Colonial Systems: Benin Kingdom", "2014", "The Oba of Benin was assisted in administration by an executive hereditary council of kingmakers known as the:", ["Uzama Nihiron", "Oyomesi", "Ogboni", "Waziri"], 0, "The Uzama (seven hereditary kingmakers led by the Oliha) formed the supreme advisory council to the Oba of Benin.", "Medium"),
    ("gov_m2_31", "Colonial Administration: Crown Colony", "2012", "Lagos was ceded to the British Crown and became a Crown Colony in the year:", ["1861", "1914", "1900", "1886"], 0, "Lagos was annexed and proclaimed a British Crown Colony under the Treaty of Cession in 1861.", "Easy"),
